class HelloFlutterSoLoud extends StatefulWidget {
  const HelloFlutterSoLoud({super.key});

  @override
  State createState() => _HelloFlutterSoLoudState();
}

class _HelloFlutterSoLoudState extends State {
  AudioSource? currentSound;

  @override
  void dispose() {
    SoLoud.instance.deinit();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    if (!SoLoud.instance.isInitialized) return const SizedBox.shrink();

    return Scaffold(
      body: Center(
        child: ElevatedButton(
          onPressed: () async {
            await SoLoud.instance.disposeAllSources();

            if (kIsWeb) {
              &#47;&#47;&#47; load the audio file using [LoadMode.disk] (better for the
              &#47;&#47;&#47; Web platform).
              currentSound = await SoLoud.instance.loadAsset(
                'assets&#47;audio&#47;8_bit_mentality.mp3',
                mode: LoadMode.disk,
              );
            } else {
              &#47;&#47;&#47; load the audio file
              currentSound = await SoLoud.instance
                  .loadAsset('assets&#47;audio&#47;8_bit_mentality.mp3');
            }

            &#47;&#47;&#47; play it
            await SoLoud.instance.play(currentSound!);
          },
          child: const Text(
            'play asset',
            textAlign: TextAlign.center,
          ),
        ),
      ),
    );
  }
}

