              ),
              Text(
                '${_timezone?.identifier ?? 'Unknown'} - ${_timezone?.localizedName?.name ?? 'Unknown'}',
                key: const ValueKey('timeZoneLabel'),
              ),
              const SizedBox(height: 12),
              Text(
                'Available Time Zones (${_availableTimezones.length})',
