    FlutterSharingIntent.instance
        .getInitialSharing()
        .then((List value) {
      if (kDebugMode) {
        print(
            "Shared: getInitialMedia => ${value.map((f) => f.value).join(",")}");
      }
      setState(() {
        list = value;
      });
    });
  }

