    final registration = await register(service);
    setState(() {
      registrations.add(registration);
    });
  }

  Future dismissRegistration(Registration registration) async {
    setState(() {
      &#47;&#47;&#47; remove fast, without confirmation, to avoid "onDismissed" error.
