void main() async {
  var vm = ApolloVM();

  var codeUnit = SourceCodeUnit(
      'dart',
      r'''

      class Foo {

          int main(List args) {
            var title = args[0];
            var a = args[1];
            var b = args[2] ~&#47; 2;
            var c = args[3] * 3;

            if (c > 120) {
              c = 120 ;
            }

            var str = 'variables> a: $a ; b: $b ; c: $c' ;
            var sumAB = a + b ;
            var sumABC = a + b + c;

            print(str);
            print(title);
            print(sumAB);
            print(sumABC);

            &#47;&#47; Map:
            var map = {
            'a': a,
            'b': b,
            'c': c,
            'sumAB': sumAB,
            "sumABC": sumABC,
            };

            print('Map: $map');
            print('Map `b`: ${map['b']}');

            return map['sumABC'];
          }

      }

      ''',
      id: 'test');

  var loadOK = await vm.loadCodeUnit(codeUnit);

  if (!loadOK) {
    print("Can't load source!");
    return;
  }

  print('---------------------------------------');

  var dartRunner = vm.createRunner('dart')!;

  &#47;&#47; Map the `print` function in the VM:
  dartRunner.externalPrintFunction = (o) => print("» $o");

  var astValue = await dartRunner.executeClassMethod(
    '',
    'Foo',
    'main',
    positionalParameters: [
      ['Sums:', 10, 30, 50]
    ],
  );

  var result = astValue.getValueNoContext();
  print('Result: $result');

  print('---------------------------------------');

  &#47;&#47; Regenerate code in Dart:
  var codeStorageDart = vm.generateAllCodeIn('dart');
  var allSourcesDart = codeStorageDart.writeAllSources();
  print(allSourcesDart);

  print('---------------------------------------');

  &#47;&#47; Regenerate code in Java11:
  var codeStorageJava = vm.generateAllCodeIn('java11');
  var allSourcesJava = codeStorageJava.writeAllSources();
  print(allSourcesJava);
}

