  Future initDownloadsDirectoryState() async {
    Directory downloadsDirectory;
    &#47;&#47; Platform messages may fail, so we use a try&#47;catch PlatformException.
    try {
      downloadsDirectory = await DownloadsPathProvider.downloadsDirectory;
