          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            CupertinoButton(
              color: CupertinoColors.activeBlue,
              child: const Text('Throttle'),
              onPressed: () {
                throttle();
              },
            ),
          ],
        ),
      ),
    );
  }
}

