    return Preset(
      name: name,
      borderRadius: borderRadius ?? this.borderRadius,
      shadowGradient: shadowGradient != defaultGradient ? shadowGradient : this.shadowGradient,
      shadowBlurRadius: shadowBlurRadius ?? this.shadowBlurRadius,
