class _MyHomePageState extends State {
  late GlobalKey formKey;
  var _autoValidateMode = AutovalidateMode.disabled;

  @override
  void initState() {
    super.initState();
    formKey = GlobalKey();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Text(widget.title),
      ),
      body: Container(
        padding: const EdgeInsets.all(40.0),
        child: Form(
          autovalidateMode: _autoValidateMode,
          key: formKey,
          child: Column(
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              TextFormField(
                key: const Key("username"),
                validator: [
                  FLValidator.required,
                  FLValidator.max(10),
                  FLValidator.email,
                  FLValidator.uppercase,
                  FLValidator.same("man"),
                ].validate(attribute: "Username fullname"),
              ),
              const SizedBox(height: 10),
              TextFormField(
                key: const Key("customval"),
                decoration:
                    const InputDecoration(hintText: "Custom validation"),
                validator: [FLValidator.required, customValidation].v,
              ),
              const SizedBox(height: 10),
              TextFormField(
                key: const Key("email"),
                validator: 'required|email'.v,
              ),
              const SizedBox(height: 10),
              TextFormField(
                key: const Key("fullname"),
                validator: ['required', 'uppercase'].v,
              ),
              const SizedBox(height: 10),
              ElevatedButton(
                onPressed: handleSubmit,
                child: const Text("Submit"),
              )
            ],
          ),
        ),
      ),
    );
  }

  void handleSubmit() {
    final formState = formKey.currentState;
    if (formState == null) {
      return;
    }
    if (!formState.validate()) {
      _autoValidateMode = AutovalidateMode.always;
    }
  }
}

