class DioFactory {
  Future create({
    required String baseUrl,
    required bool isDebugViewEnabled,
  }) async {
    final dio = Dio(
      BaseOptions(
        baseUrl: baseUrl,
        responseType: ResponseType.json,
        headers: {
          Headers.acceptHeader: Headers.jsonContentType,
          Headers.contentTypeHeader: Headers.jsonContentType,
        },
      ),
    );

    if (isDebugViewEnabled) {
      final prefs = await SharedPreferences.getInstance();

      dio.interceptors.add(
        NetworkLoggerInterceptor(),
      );

      dio.httpClientAdapter = ChiliHttpClientAdapter(
        proxyUrl: prefs.getString(
          'proxyUrl',
        ),
      );
    }

    return dio;
  }
}

class ApiClient {
  final Dio _dio;

  const ApiClient({
    required Dio dio,
  }) : _dio = dio;

  void makeSimpleRequest(int articleId) =>
      _dio.get(_ApiEndpoints._articles(articleId));
}

class _ApiEndpoints {
  static _articles(id) => '&#47;articles&#47;$id';
}

