                    onChanged: (val) {
                      setState(() {
                        showUI = val!;
                      });
                    }),
              ),
              Slider(
                divisions: sliderDivisions,
                value: currentVolume,
                onChanged: onValueChanged,
                &#47;&#47; onChangeEnd: onValueChanged,
              ),
              Text('Volume: $currentVolume%'),

