    D.log("onEvent: $event");
  };

  builder.withHandlers(
    onStatusChanged: onStatusChanged,
    onEvent: onEvent
  );

  void onLog(SNSLogLevel level, String message) {
    D.log('onLog: \'$level\' - $message');
