class _MyAppState extends State {
  VolumeKey? lastKey;
  int currentVol = 0;

  @override
  void initState() {
    super.initState();
    initPlatformState();
  }

  &#47;&#47; Platform messages are asynchronous, so we initialize in an async method.
  Future initPlatformState() async {
    VolumeListener.addListener((VolumeKey event) {
      setState(() {
        lastKey = event;
        currentVol += (event == VolumeKey.up ? 1 : -1);
      });
    });
  }

  @override
  void dispose() {
    VolumeListener.removeListener();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      home: Scaffold(
        appBar: AppBar(
          title: const Text('Plugin example app'),
        ),
        body: Center(
          child: Text('Total volume:  $currentVol\n'),
        ),
      ),
    );
  }
}

