class _MyAppState extends State {
  &#47;&#47; Platform messages are asynchronous, so we initialize in an async method.

  String? thumbnail;
  Uint8List? thumbanilBytes;

  Future getVideoFile() async {
    if (kIsWeb) {
      final files = await FilePicker.platform.pickFiles();

      if (files != null && files.files.isNotEmpty) {
        thumbanilBytes = await FlutterVideoThumbnailPlus.thumbnailDataWeb(
            videoBytes: files.files.first.bytes ?? Uint8List(0));
      }
    } else {
      final file = await ImagePicker().pickVideo(source: ImageSource.gallery);
      thumbnail = await FlutterVideoThumbnailPlus.thumbnailFile(
          video: file?.path ?? '');
    }
    setState(() {});
  }

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      home: Scaffold(
        appBar: AppBar(
          title: const Text('Plugin example app'),
        ),
        body: Center(
          child: Column(
            mainAxisAlignment: MainAxisAlignment.center,
            crossAxisAlignment: CrossAxisAlignment.center,
            children: [
              InkWell(
                onTap: () {
                  getVideoFile();
                },
                child: Text('Running on: \n$thumbnail'),
              ),
              if (thumbnail != null && !kIsWeb) ...[
                Image.file(
                  File(thumbnail ?? ''),
                  height: 200,
                ),
              ] else if (thumbanilBytes != null) ...[
                Image.memory(
                  thumbanilBytes ?? Uint8List(0),
                )
              ]
            ],
          ),
        ),
      ),
    );
  }
}

